import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'
import { renderHook, act } from '@testing-library/react'
import { useToast } from '@/hooks/useToast'

describe('useToast', () => {
  beforeEach(() => {
    vi.useFakeTimers()
  })

  afterEach(() => {
    vi.useRealTimers()
  })

  it('starts with empty toasts', () => {
    const { result } = renderHook(() => useToast())
    expect(result.current.toasts).toEqual([])
  })

  it('adds a toast with default type', () => {
    const { result } = renderHook(() => useToast())
    act(() => {
      result.current.addToast('Hello')
    })
    expect(result.current.toasts).toHaveLength(1)
    expect(result.current.toasts[0].message).toBe('Hello')
    expect(result.current.toasts[0].type).toBe('info')
  })

  it('adds a toast with success type', () => {
    const { result } = renderHook(() => useToast())
    act(() => {
      result.current.addToast('Success!', 'success')
    })
    expect(result.current.toasts[0].type).toBe('success')
  })

  it('adds a toast with error type', () => {
    const { result } = renderHook(() => useToast())
    act(() => {
      result.current.addToast('Error!', 'error')
    })
    expect(result.current.toasts[0].type).toBe('error')
  })

  it('generates unique IDs', () => {
    const { result } = renderHook(() => useToast())
    act(() => {
      result.current.addToast('First')
      result.current.addToast('Second')
    })
    expect(result.current.toasts[0].id).not.toBe(result.current.toasts[1].id)
  })

  it('removes a toast by ID', () => {
    const { result } = renderHook(() => useToast())
    act(() => {
      result.current.addToast('First')
      result.current.addToast('Second')
    })
    const firstId = result.current.toasts[0].id
    act(() => {
      result.current.removeToast(firstId)
    })
    expect(result.current.toasts).toHaveLength(1)
    expect(result.current.toasts[0].message).toBe('Second')
  })

  it('auto-removes toast after 3 seconds', () => {
    const { result } = renderHook(() => useToast())
    act(() => {
      result.current.addToast('Auto remove')
    })
    expect(result.current.toasts).toHaveLength(1)
    act(() => {
      vi.advanceTimersByTime(3000)
    })
    expect(result.current.toasts).toHaveLength(0)
  })

  it('handles multiple toasts', () => {
    const { result } = renderHook(() => useToast())
    act(() => {
      result.current.addToast('One')
      result.current.addToast('Two')
      result.current.addToast('Three')
    })
    expect(result.current.toasts).toHaveLength(3)
  })
})

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'
import { renderHook, waitFor } from '@testing-library/react'
import { QueryClient, QueryClientProvider } from '@tanstack/react-query'

// Mocks hoisted para que vi.mock los vea
const { mockFrom, mockSelect, mockOrder, mockEq, mockMaybeSingle } = vi.hoisted(() => ({
  mockFrom: vi.fn(),
  mockSelect: vi.fn(),
  mockOrder: vi.fn(),
  mockEq: vi.fn(),
  mockMaybeSingle: vi.fn(),
}))

vi.mock('@/lib/supabase/client', () => ({
  supabaseBrowser: vi.fn(() => ({
    from: mockFrom,
  })),
}))

import { usePacks } from '@/hooks/usePacks'

/**
 * Crea un objeto que es a la vez encadenable (tiene .eq, .order, .maybeSingle)
 * y "thenable" (tiene .then para que await funcione).
 * Simula el comportamiento del query builder de Supabase.
 */
function chainable(result: { data: unknown; error: Error | null }) {
  const promise = Promise.resolve(result)
  return Object.assign(promise, {
    order: mockOrder,
    eq: mockEq,
    maybeSingle: mockMaybeSingle,
  })
}

function createWrapper() {
  const queryClient = new QueryClient({
    defaultOptions: { queries: { retry: false } },
  })
  return function Wrapper({ children }: { children: React.ReactNode }) {
    return <QueryClientProvider client={queryClient}>{children}</QueryClientProvider>
  }
}

describe('usePacks', () => {
  beforeEach(() => {
    vi.clearAllMocks()

    // Valor por defecto: éxito vacío
    const ok = { data: [], error: null }

    mockFrom.mockReturnValue({ select: mockSelect })
    mockSelect.mockReturnValue(chainable(ok))
    mockOrder.mockReturnValue(chainable(ok))
    mockEq.mockReturnValue(chainable(ok))
    mockMaybeSingle.mockResolvedValue({ data: null, error: null })
  })

  afterEach(() => {
    vi.restoreAllMocks()
  })

  it('starts with empty packs', () => {
    const { result } = renderHook(() => usePacks(), { wrapper: createWrapper() })
    expect(result.current.packs).toEqual([])
  })

  it('fetches packs without shopId filter', async () => {
    const mockData = [{ id: 'p-1', title: 'Pack 1', shop: { name: 'Shop 1' } }]
    // order() es el terminal en este caso → devuelve los datos
    mockOrder.mockReturnValue(chainable({ data: mockData, error: null }))

    const { result } = renderHook(() => usePacks(), { wrapper: createWrapper() })

    await waitFor(() => expect(result.current.loading).toBe(false))
    expect(result.current.packs).toEqual(mockData)
    expect(mockFrom).toHaveBeenCalledWith('packs')
    expect(mockSelect).toHaveBeenCalled()
    expect(mockOrder).toHaveBeenCalledWith('created_at', { ascending: false })
  })

  it('fetches packs with shopId filter', async () => {
    const mockData = [{ id: 'p-2', title: 'Pack 2', shop: { name: 'Shop 2' } }]
    // eq() es el terminal en este caso
    mockEq.mockReturnValue(chainable({ data: mockData, error: null }))

    const { result } = renderHook(() => usePacks('shop-1'), { wrapper: createWrapper() })

    await waitFor(() => expect(result.current.loading).toBe(false))
    expect(result.current.packs).toEqual(mockData)
    expect(mockFrom).toHaveBeenCalledWith('packs')
    expect(mockEq).toHaveBeenCalledWith('shop_id', 'shop-1')
  })

  it('returns error when query fails', async () => {
    mockOrder.mockReturnValue(chainable({ data: null, error: new Error('DB error') }))

    const { result } = renderHook(() => usePacks(), { wrapper: createWrapper() })

    await waitFor(() => expect(result.current.error).toBe('DB error'))
  })

  it('getPackById fetches single pack', async () => {
    const mockPack = { id: 'p-1', title: 'Pack 1', shop: { name: 'Shop 1' } }
    // fetchPacks (sin shopId) → order es terminal, devuelve vacío
    mockOrder.mockReturnValue(chainable({ data: [], error: null }))
    // fetchPackById → maybeSingle es terminal, devuelve el pack
    mockMaybeSingle.mockResolvedValue({ data: mockPack, error: null })

    const { result } = renderHook(() => usePacks(), { wrapper: createWrapper() })
    await waitFor(() => expect(result.current.loading).toBe(false))

    const pack = await result.current.getPackById('p-1')
    expect(pack).toEqual(mockPack)
    expect(mockFrom).toHaveBeenCalledWith('packs')
    expect(mockEq).toHaveBeenCalledWith('id', 'p-1')
    expect(mockMaybeSingle).toHaveBeenCalled()
  })
})

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { renderHook, act, waitFor } from '@testing-library/react'
import { useProfile } from '@/hooks/useProfile'
import { supabaseBrowser } from '@/lib/supabase/client'

const mockFrom = vi.fn()
const mockUpdate = vi.fn()
const mockEq = vi.fn()
const mockUpload = vi.fn()
const mockGetPublicUrl = vi.fn()

function setupMockClient() {
  mockEq.mockReturnThis()
  mockUpdate.mockReturnThis()
  mockUpload.mockResolvedValue({ error: null })
  mockGetPublicUrl.mockReturnValue({ data: { publicUrl: 'https://example.com/avatar.jpg' } })

  mockFrom.mockImplementation((table: string) => {
    if (table === 'user_profiles') {
      return { update: mockUpdate, eq: mockEq }
    }
    return {}
  })
  ;(supabaseBrowser as any).mockReturnValue({
    from: mockFrom,
    storage: {
      from: () => ({
        upload: mockUpload,
        getPublicUrl: mockGetPublicUrl,
      }),
    },
  })
}

const fakeFile = new File(['test'], 'avatar.png', { type: 'image/png' })

describe('useProfile', () => {
  beforeEach(() => {
    vi.clearAllMocks()
    setupMockClient()
  })

  it('updateProfile calls supabase update', async () => {
    const { result } = renderHook(() => useProfile())

    await act(async () => {
      await result.current.updateProfile('user-1', { name: 'New Name' })
    })

    expect(mockUpdate).toHaveBeenCalledWith({ name: 'New Name' })
    expect(mockEq).toHaveBeenCalledWith('id', 'user-1')
  })

  it('uploadAvatar uploads file and updates profile', async () => {
    const { result } = renderHook(() => useProfile())

    let url: string
    await act(async () => {
      url = await result.current.uploadAvatar('user-1', fakeFile)
    })

    expect(mockUpload).toHaveBeenCalled()
    expect(mockUpdate).toHaveBeenCalled()
    expect(url!).toBe('https://example.com/avatar.jpg')
  })

  it('uploadAvatar rejects invalid file type', async () => {
    const invalidFile = new File(['test'], 'test.exe', { type: 'application/x-msdownload' })
    const { result } = renderHook(() => useProfile())

    await expect(
      act(async () => {
        await result.current.uploadAvatar('user-1', invalidFile)
      }),
    ).rejects.toThrow(/Tipo de archivo no permitido/)
  })

  it('uploadAvatar rejects oversized file', async () => {
    const hugeFile = new File(['x'.repeat(6 * 1024 * 1024)], 'huge.jpg', { type: 'image/jpeg' })
    const { result } = renderHook(() => useProfile())

    await expect(
      act(async () => {
        await result.current.uploadAvatar('user-1', hugeFile)
      }),
    ).rejects.toThrow(/excede el tamaño máximo/)
  })

  it('sets uploading state during upload', async () => {
    mockUpload.mockImplementation(() => new Promise((resolve) => setTimeout(() => resolve({ error: null }), 100)))
    const { result } = renderHook(() => useProfile())

    act(() => {
