'use client'

/**
 * Lee el token CSRF de la cookie establecida por el middleware.
 * La cookie NO es HttpOnly para que el cliente JS pueda leerla.
 */
export function getCsrfToken(): string {
  if (typeof document === 'undefined') return ''

  const match = document.cookie.match(/(?:^|;\s*)csrf_token=([^;]*)/)
  return match ? decodeURIComponent(match[1]) : ''
}

/**
 * Headers por defecto para fetch a la API de Paporla.
 * Incluye el token CSRF requerido para mutaciones.
 */
export function apiHeaders(extra?: Record<string, string>): Record<string, string> {
  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': getCsrfToken(),
    ...extra,
  }
  return headers
}

/**
 * Wrapper de fetch que incluye automáticamente el token CSRF
 * y parsea la respuesta JSON.
 */
export async function apiFetch<T>(url: string, options?: RequestInit): Promise<T> {
  const headers = {
    ...apiHeaders(),
    ...(options?.headers as Record<string, string> | undefined),
  }

  const response = await fetch(url, {
    ...options,
    headers,
  })

  const data = await response.json()
  if (!data.success) throw new Error(data.error ?? 'Error en la solicitud')
  return data as T
}

import { NextRequest, NextResponse } from 'next/server'
import crypto from 'crypto'

// ============================================
// CSRF Protection — Double-submit cookie pattern
// ============================================
//
// Genera un token CSRF por sesión, lo almacena en una cookie
// y exige que las mutaciones API incluyan el mismo token
// en el header X-CSRF-Token.
//
// La cookie NO tiene HttpOnly para que el cliente JS pueda leerla
// y enviarla de vuelta en el header. Esto es seguro porque:
// - Un atacante en otro dominio no puede leer la cookie (SameSite Lax)
// - Un atacante no puede escribir el header desde otro origen (CORS)

const CSRF_COOKIE = 'csrf_token'
const CSRF_HEADER = 'X-CSRF-Token'

function generateToken(): string {
  return crypto.randomBytes(32).toString('hex')
}

/**
 * Aplica la cookie CSRF a la respuesta si no existe.
 * Debe llamarse en middleware.ts en la respuesta next().
 */
export function setCsrfCookie(response: NextResponse, existingToken?: string): string {
  const token = existingToken ?? generateToken()
  response.cookies.set(CSRF_COOKIE, token, {
    httpOnly: false, // El cliente necesita leerla para enviarla en el header
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    path: '/',
    maxAge: 60 * 60 * 24, // 24 horas
  })
  return token
}

/**
 * Valida que la petición incluya el token CSRF correcto.
 * Retorna null si es válido, o un NextResponse de error si no.
 */
export function validateCsrf(request: NextRequest): NextResponse | null {
  // Solo validar mutaciones
  const method = request.method
  if (!['POST', 'PUT', 'PATCH', 'DELETE'].includes(method)) {
    return null
  }

  const cookieToken = request.cookies.get(CSRF_COOKIE)?.value
  const headerToken = request.headers.get(CSRF_HEADER)

  if (!cookieToken || !headerToken) {
    return NextResponse.json(
      { success: false, error: 'Token CSRF requerido para mutaciones' },
      { status: 403 },
    )
  }

  // Comparación en tiempo constante para evitar timing attacks
  if (cookieToken.length !== headerToken.length) {
    return NextResponse.json(
      { success: false, error: 'Token CSRF inválido' },
      { status: 403 },
    )
  }

  const valid = crypto.timingSafeEqual(Buffer.from(cookieToken), Buffer.from(headerToken))
  if (!valid) {
    return NextResponse.json(
      { success: false, error: 'Token CSRF inválido' },
      { status: 403 },
    )
  }

  return null
}

import { getSupabaseAdmin } from '@/lib/supabase/admin'

interface SendNotificationParams {
  userId: string
  type: string
  message: string
  reservationId?: string
}

export async function sendNotification({ userId, type, message, reservationId }: SendNotificationParams) {
  try {
    const supabase = getSupabaseAdmin()
    const { error } = await supabase.from('notifications').insert({
      user_id: userId,
      type,
      message,
      reservation_id: reservationId ?? null,
      is_read: false,
      sent_at: new Date().toISOString(),
    })
    if (error) {
      console.error('[sendNotification] Error:', error.message)
      return false
    }
    return true
  } catch (err) {
    console.error('[sendNotification] Error:', err)
    return false
  }
}

export async function sendBatchNotifications(notifications: SendNotificationParams[]) {
  try {
    const supabase = getSupabaseAdmin()
    const records = notifications.map((n) => ({
      user_id: n.userId,
      type: n.type,
      message: n.message,
      reservation_id: n.reservationId ?? null,
      is_read: false,
      sent_at: new Date().toISOString(),
    }))
    const { error } = await supabase.from('notifications').insert(records)
    if (error) {
      console.error('[sendBatchNotifications] Error:', error.message)
      return false
    }
    return true
  } catch (err) {
    console.error('[sendBatchNotifications] Error:', err)
    return false
  }
}

