'use client'

import { useEffect, useState, useCallback, useRef } from 'react'
import { supabaseBrowser } from '@/lib/supabase/client'
import { useAuth } from './useAuth'

interface Shop {
  id: string
  name: string
  address: string | null
  city: string | null
  phone: string | null
  verified: boolean
  rating: number | null
  logo_url: string | null
  cover_url: string | null
}

interface FavoriteShop {
  id: string
  shop_id: string
  shop: Shop
}

export function useFavorites() {
  const { user } = useAuth()
  const supabase = supabaseBrowser()
  const [favorites, setFavorites] = useState<FavoriteShop[]>([])
  const [loading, setLoading] = useState(true)
  const [favoriteShopIds, setFavoriteShopIds] = useState<Set<string>>(new Set())
  const isFirstLoad = useRef(true)

  const loadFavorites = useCallback(async () => {
    if (!user) {
      setFavorites([])
      setFavoriteShopIds(new Set())
      setLoading(false)
      return
    }

    // Solo mostrar loading en la primera carga
    if (isFirstLoad.current) {
      setLoading(true)
    }

    const { data, error } = await supabase
      .from('favorites')
      .select(
        `
        id,
        shop_id,
        shop:shops (
          id,
          name,
          address,
          city,
          phone,
          verified,
          rating,
          logo_url,
          cover_url
        )
      `,
      )
      .eq('user_id', user.id)
      .order('created_at', { ascending: false })

    if (error) {
      console.error('Error loading favorites:', error)
    } else {
      const typedData = data as unknown as FavoriteShop[]
      setFavorites(typedData ?? [])
      setFavoriteShopIds(new Set(typedData?.map((f) => f.shop_id) || []))
    }

    setLoading(false)
    isFirstLoad.current = false
  }, [user, supabase])

  useEffect(() => {
    loadFavorites()
  }, [loadFavorites])

  const addFavorite = async (shopId: string) => {
    if (!user) return false

    const { error } = await supabase.from('favorites').insert({
      user_id: user.id,
      shop_id: shopId,
    })

    if (error) {
      console.error('Error adding favorite:', error)
      return false
    }

    await loadFavorites()
    return true
  }

  const removeFavorite = async (shopId: string) => {
    if (!user) return false

    const { error } = await supabase.from('favorites').delete().eq('user_id', user.id).eq('shop_id', shopId)

    if (error) {
      console.error('Error removing favorite:', error)
      return false
    }

    await loadFavorites()
    return true
  }

  const toggleFavorite = async (shopId: string) => {
    if (favoriteShopIds.has(shopId)) {
      return await removeFavorite(shopId)
    } else {
      return await addFavorite(shopId)
    }
  }

  const isFavorite = (shopId: string) => favoriteShopIds.has(shopId)

  return {
    favorites,
    favoriteShopIds,
    loading,
    addFavorite,
    removeFavorite,
    toggleFavorite,
    isFavorite,
    reload: loadFavorites,
  }
}

'use client'

import { useEffect, useState, useCallback } from 'react'
import { supabaseBrowser } from '@/lib/supabase/client'
import { useAuth } from './useAuth'

export interface Notification {
  id: string
  user_id: string
  reservation_id: string | null
  type:
    | 'pickup_reminder'
    | 'cancellation'
    | 'confirmation'
    | 'new_pack'
    | 'shop_verified'
    | 'new_reservation'
    | 'user_cancelled'
    | 'pickup_completed'
    | 'new_user'
    | 'new_shop'
    | 'incidence'
  message: string
  is_read: boolean
  sent_at: string | null
  created_at: string
}

export function useNotifications() {
  const { user } = useAuth()
  const supabase = supabaseBrowser()
  const [notifications, setNotifications] = useState<Notification[]>([])
  const [unreadCount, setUnreadCount] = useState(0)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  const loadNotifications = useCallback(async () => {
    if (!user) {
      setNotifications([])
      setUnreadCount(0)
      setLoading(false)
      return
    }

    setLoading(true)
    setError(null)

    const { data, error: queryError } = await supabase
      .from('notifications')
      .select('*')
      .eq('user_id', user.id)
      .order('created_at', { ascending: false })

    if (queryError) {
      setError(queryError.message)
    } else {
      setNotifications(data ?? [])
      setUnreadCount(data?.filter((n) => !n.is_read).length ?? 0)
    }

    setLoading(false)
  }, [user, supabase])

  // Carga inicial
  useEffect(() => {
    loadNotifications()
  }, [loadNotifications])

  // Suscripción a cambios en tiempo real
  useEffect(() => {
    const userId = user?.id ?? null
    if (!userId) return

    // Nombre único por montaje para evitar colisiones en React Strict Mode
    const channelName = `notifications-${userId}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`
    const channel = supabase.channel(channelName)
      .on(
        'postgres_changes',
        { event: 'INSERT', schema: 'public', table: 'notifications', filter: `user_id=eq.${userId}` },
        (payload) => {
          const newNotification = payload.new as Notification
          setNotifications((prev) => [newNotification, ...prev])
          setUnreadCount((prev) => prev + 1)
        },
      )
      .on(
        'postgres_changes',
        { event: 'UPDATE', schema: 'public', table: 'notifications', filter: `user_id=eq.${userId}` },
        (payload) => {
          const updated = payload.new as Notification
          setNotifications((prev) => {
            const updatedList = prev.map((n) => (n.id === updated.id ? updated : n))
            setUnreadCount(updatedList.filter((n) => !n.is_read).length)
            return updatedList
          })
        },
      )
      .on(
        'postgres_changes',
        { event: 'DELETE', schema: 'public', table: 'notifications', filter: `user_id=eq.${userId}` },
        (payload) => {
          const deletedId = payload.old.id as string
          setNotifications((prev) => {
            const wasUnread = prev.find((n) => n.id === deletedId)?.is_read === false
            if (wasUnread) setUnreadCount((c) => Math.max(0, c - 1))
            return prev.filter((n) => n.id !== deletedId)
          })
        },
      )
      .subscribe()

    // Cleanup: eliminar canal al cambiar de usuario o desmontar
    return () => {
      supabase.removeChannel(channel).catch(() => {})
    }
  }, [user?.id, supabase])

  const markAsRead = useCallback(
    async (notificationId: string) => {
      const { error: updateError } = await supabase
        .from('notifications')
        .update({ is_read: true })
        .eq('id', notificationId)

      if (!updateError) {
        setNotifications((prev) => prev.map((n) => (n.id === notificationId ? { ...n, is_read: true } : n)))
        setUnreadCount((prev) => Math.max(0, prev - 1))
      }
    },
    [supabase],
  )

  const markAllAsRead = useCallback(async () => {
    const unreadIds = notifications.filter((n) => !n.is_read).map((n) => n.id)
    if (unreadIds.length === 0) return

    const { error: updateError } = await supabase.from('notifications').update({ is_read: true }).in('id', unreadIds)

    if (!updateError) {
      setNotifications((prev) => prev.map((n) => ({ ...n, is_read: true })))
      setUnreadCount(0)
    }
  }, [notifications, supabase])

  const deleteNotification = useCallback(
    async (notificationId: string) => {
      const { error: deleteError } = await supabase.from('notifications').delete().eq('id', notificationId)

      if (!deleteError) {
        const deleted = notifications.find((n) => n.id === notificationId)
        setNotifications((prev) => prev.filter((n) => n.id !== notificationId))
        if (deleted && !deleted.is_read) {
          setUnreadCount((prev) => Math.max(0, prev - 1))
        }
      }
    },
    [notifications, supabase],
  )

  return {
    notifications,
    unreadCount,
    loading,
    error,
    markAsRead,
    markAllAsRead,
    deleteNotification,
  }
}

'use client'

import { useState, useEffect, useMemo } from 'react'
import { supabaseBrowser } from '@/lib/supabase/client'
import type { PublicPack } from '@/components/packs/PackCardPublic'

interface Filters {
  search: string
  minPrice: number
  maxPrice: number
  showAvailableOnly: boolean
  city: string
}

export function usePublicPacks() {
  const supabase = supabaseBrowser()
  const [allPacks, setAllPacks] = useState<PublicPack[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [filters, setFilters] = useState<Filters>({
    search: '',
    minPrice: 0,
    maxPrice: 100000,
    showAvailableOnly: false,
    city: '',
  })

  const loadPacks = async () => {
    setLoading(true)
    setError('')
    try {
      const { data, error: err } = await supabase
        .from('available_packs')
        .select('*')
        .order('created_at', { ascending: false })
      if (err) setError(err.message)
      else setAllPacks((data as PublicPack[]) || [])
    } catch {
      setError('Error al cargar packs')
    }
    setLoading(false)
  }

  useEffect(() => {
    loadPacks()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  const filteredPacks = useMemo(() => {
    let f = [...allPacks]
    if (filters.search) {
      const q = filters.search.toLowerCase()
      f = f.filter((p) => p.title?.toLowerCase().includes(q) || p.description?.toLowerCase().includes(q))
    }
    if (filters.minPrice > 0) f = f.filter((p) => p.price_cents >= filters.minPrice)
    if (filters.maxPrice < 100000) f = f.filter((p) => p.price_cents <= filters.maxPrice)
    if (filters.showAvailableOnly) f = f.filter((p) => p.remaining_stock > 0)
    if (filters.city) f = f.filter((p) => p.shop_city === filters.city)
    return f
  }, [allPacks, filters])

  return { allPacks, packs: filteredPacks, loading, error, setError, filters, setFilters, reload: loadPacks }
}

