const VALID_EMAIL_TYPES = ['welcome', 'reservation', 'password_reset', 'pickup_reminder'] as const

function isValidEmail(email: string): boolean {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)
}

const resend = new Resend(process.env.RESEND_API_KEY)
const senderEmail = process.env.RESEND_FROM_EMAIL ?? 'noreply@paporla.com'

export async function POST(request: Request) {
  try {
    const supabase = await createClient()
    const {
      data: { user },
    } = await supabase.auth.getUser()

    if (!user) {
      return NextResponse.json({ success: false, error: 'No autorizado' }, { status: 401 })
    }

    let body: Record<string, unknown>
    try {
      body = await request.json()
    } catch {
      return NextResponse.json({ success: false, error: 'Cuerpo de solicitud inválido' }, { status: 400 })
    }

    const { type, email, data } = body as {
      type?: string
      email?: string
      data?: Record<string, unknown>
    }

    if (!email || !type) {
      return NextResponse.json({ success: false, error: 'Faltan campos: email y type son requeridos' }, { status: 400 })
    }

    if (!isValidEmail(email)) {
      return NextResponse.json({ success: false, error: 'Formato de email inválido' }, { status: 400 })
    }

    if (!VALID_EMAIL_TYPES.includes(type as (typeof VALID_EMAIL_TYPES)[number])) {
      return NextResponse.json({ success: false, error: 'Tipo de correo no válido' }, { status: 400 })
    }

    const isSystemEmail = email === user.email
    if (!isSystemEmail) {
      return NextResponse.json(
        { success: false, error: 'Solo puedes enviar emails a tu propia dirección' },
        { status: 403 },
      )
    }

    const safeData = data ?? {}

    let subject = ''
    let html = ''
    let text = ''

    switch (type) {
      case 'welcome':
        subject = 'Bienvenido a Paporla - Rescate Alimentario'
        html = welcomeTemplate(String(safeData.name ?? 'Usuario'))
        text = `Bienvenido a Paporla, ${String(safeData.name ?? 'Usuario')}! Gracias por unirte a la comunidad que esta cambiando la forma de alimentarnos. Explora packs disponibles en nuestra web.`
        break

      case 'reservation':
        subject = `Tu reserva de ${String(safeData.packTitle ?? 'Pack')} esta confirmada - Paporla`
        html = reservationConfirmationTemplate({
          userName: String(safeData.userName ?? 'Usuario'),
          packTitle: String(safeData.packTitle ?? 'Pack'),
          shopName: String(safeData.shopName ?? 'Comercio'),
          shopAddress: safeData.shopAddress ? String(safeData.shopAddress) : null,
          pickupCode: String(safeData.pickupCode ?? 'XXXXXX'),
          pickupDate: safeData.pickupDate ? String(safeData.pickupDate) : null,
          pickupTime: safeData.pickupTime ? String(safeData.pickupTime) : null,
          price: String(safeData.price ?? ''),
        })
        text = `Tu reserva esta confirmada. Pack: ${String(safeData.packTitle ?? 'Pack')}. Comercio: ${String(safeData.shopName ?? 'Comercio')}. Codigo de recogida: ${String(safeData.pickupCode ?? 'XXXXXX')}.`
        break

      case 'password_reset':
        subject = 'Restablece tu contraseña - Paporla'
        html = passwordResetTemplate(String(safeData.resetLink ?? ''))
        text = `Recibimos una solicitud para restablecer tu contraseña. Haz clic en este enlace: ${safeData.resetLink ?? ''}`
        break

      case 'pickup_reminder':
        subject = `Recuerda recoger tu pack de ${String(safeData.packTitle ?? 'Pack')} hoy - Paporla`
        html = pickupReminderTemplate({
          userName: String(safeData.userName ?? 'Usuario'),
          packTitle: String(safeData.packTitle ?? 'Pack'),
          shopName: String(safeData.shopName ?? 'Comercio'),
          shopAddress: safeData.shopAddress ? String(safeData.shopAddress) : null,
          pickupCode: String(safeData.pickupCode ?? 'XXXXXX'),
          pickupDate: String(safeData.pickupDate ?? ''),
          pickupTime: safeData.pickupTime ? String(safeData.pickupTime) : null,
        })
        text = `Recuerda recoger tu pack hoy. Pack: ${String(safeData.packTitle ?? 'Pack')}. Comercio: ${String(safeData.shopName ?? 'Comercio')}. Codigo: ${String(safeData.pickupCode ?? 'XXXXXX')}.`
        break
    }

    const { data: res, error } = await resend.emails.send({
      from: `Paporla <${senderEmail}>`,
      to: email,
      subject,
      html,
      text,
      headers: {
        'X-Priority': '3',
        'X-Mailer': 'Paporla',
      },
    })

    if (error) {
      console.error(`[Email API Error] ${type}:`, error)
      return NextResponse.json({ success: false, error: error.message }, { status: 500 })
    }

    console.warn(`[Email API Sent] ${type} to:`, email)
    return NextResponse.json({ success: true, data: res })
  } catch (err: unknown) {
    console.error('[Email API Exception]:', err)
    const message = err instanceof Error ? err.message : 'Error interno del servidor'
    return NextResponse.json({ success: false, error: message }, { status: 500 })
  }
}

import { NextResponse } from 'next/server'
import { createClient } from '@/lib/supabase/server'

export async function GET() {
  const start = Date.now()

  try {
    const supabase = await createClient()
    const { error } = await supabase.from('user_profiles').select('id').limit(1).maybeSingle()

    if (error) {
      return NextResponse.json(
        {
          status: 'degraded',
          timestamp: new Date().toISOString(),
          uptime: process.uptime(),
          database: 'error',
          error: error.message,
        },
        { status: 503 },
      )
    }

    return NextResponse.json(
      {
        status: 'healthy',
        timestamp: new Date().toISOString(),
        uptime: process.uptime(),
        database: 'connected',
        responseTimeMs: Date.now() - start,
        version: process.env.npm_package_version ?? '1.0.0',
        environment: process.env.NODE_ENV ?? 'development',
      },
      {
        headers: {
          'Cache-Control': 'no-store, must-revalidate',
        },
      },
    )
  } catch (err) {
    return NextResponse.json(
      {
        status: 'error',
        timestamp: new Date().toISOString(),
        uptime: process.uptime(),
        database: 'disconnected',
        error: err instanceof Error ? err.message : 'Unknown error',
      },
      { status: 500 },
    )
  }
}

﻿import { createClient } from '@/lib/supabase/server'
import { NextResponse } from 'next/server'
import { getPacks, createPack, updatePack, deletePack, ALLOWED_PACK_FIELDS } from '@/lib/services/packService'
import { packSchema } from '@/lib/utils/validations'

const cacheHeaders = {
  'Cache-Control': 'public, s-maxage=60, stale-while-revalidate=120',
}

interface PackResult {
  error?: string
  status?: number
  data?: unknown
}

export async function GET(request: Request) {
  const { searchParams } = new URL(request.url)
  const result = (await getPacks(
    searchParams.get('id') || undefined,
    searchParams.get('shopId') || undefined,
  )) as PackResult
  if (result.error) return NextResponse.json({ success: false, error: result.error }, { status: result.status ?? 500 })
  if (searchParams.get('id')) return NextResponse.json({ success: true, pack: result.data }, { headers: cacheHeaders })
  return NextResponse.json({ success: true, packs: result.data }, { headers: cacheHeaders })
}

export async function POST(request: Request) {
  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()
  if (!user) return NextResponse.json({ success: false, error: 'No autorizado' }, { status: 401 })

  let body: Record<string, unknown>
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ success: false, error: 'Cuerpo de solicitud inválido' }, { status: 400 })
  }

  const parsed = packSchema.safeParse(body)
  if (!parsed.success) {
    const firstError = parsed.error.errors[0]?.message ?? 'Datos inválidos'
    return NextResponse.json({ success: false, error: firstError }, { status: 400 })
  }

  const result = (await createPack(user.id, body)) as PackResult
  if (result.error) return NextResponse.json({ success: false, error: result.error }, { status: result.status ?? 500 })
  return NextResponse.json({ success: true, pack: result.data }, { status: result.status ?? 201 })
}

export async function PUT(request: Request) {
  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()
  if (!user) return NextResponse.json({ success: false, error: 'No autorizado' }, { status: 401 })

  let body: Record<string, unknown>
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ success: false, error: 'Cuerpo de solicitud inválido' }, { status: 400 })
  }

  if (!body.id) {
    return NextResponse.json({ success: false, error: 'ID del pack requerido' }, { status: 400 })
  }

  const filteredBody: Record<string, unknown> = { id: body.id }
  for (const key of ALLOWED_PACK_FIELDS) {
    if (key in body) filteredBody[key] = body[key]
  }

  const updateResult = (await updatePack(user.id, filteredBody)) as PackResult
  if (updateResult.error)
    return NextResponse.json({ success: false, error: updateResult.error }, { status: updateResult.status ?? 500 })
  return NextResponse.json({ success: true, pack: updateResult.data })
}

export async function DELETE(request: Request) {
  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()
  if (!user) return NextResponse.json({ success: false, error: 'No autorizado' }, { status: 401 })

  const { searchParams } = new URL(request.url)
  const id = searchParams.get('id')
  if (!id) return NextResponse.json({ success: false, error: 'ID del pack requerido' }, { status: 400 })

  const deleteResult = (await deletePack(user.id, id)) as PackResult & { data?: { success: boolean } }
  if (deleteResult.error)
    return NextResponse.json({ success: false, error: deleteResult.error }, { status: deleteResult.status ?? 500 })
  return NextResponse.json({ success: true, message: 'Pack eliminado' })
}

import { createClient } from '@/lib/supabase/server'
import { NextResponse } from 'next/server'
import { getUserReservations, createReservation, updateReservation } from '@/lib/services/reservationService'

async function authenticateUser() {
  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()
  return user
}

export async function GET(request: Request) {
  const user = await authenticateUser()
  if (!user) return NextResponse.json({ success: false, error: 'No autorizado' }, { status: 401 })

  const { searchParams } = new URL(request.url)
  const shopId = searchParams.get('shopId')
  const reservationId = searchParams.get('id')

  // Si se pide una reserva específica
  if (reservationId) {
    const supabase = await createClient()
    const { data, error } = await supabase
      .from('reservations')
      .select(
        '*,pack:packs(id,title,description,price_cents,image_url),shop:shops(id,name,address,phone,latitude,longitude,city),user:user_profiles(id,name,email,phone)',
      )
      .eq('id', reservationId)
      .maybeSingle()
    if (error) return NextResponse.json({ success: false, error: error.message }, { status: 500 })
    return NextResponse.json({ success: true, reservation: data })
  }

  const result = (await getUserReservations(user.id, shopId ?? undefined)) as {
    error?: string
    status?: number
    data?: unknown
  }
  if (result.error) return NextResponse.json({ success: false, error: result.error }, { status: result.status ?? 500 })
  return NextResponse.json({ success: true, reservations: result.data })
}

export async function POST(request: Request) {
  const user = await authenticateUser()
  if (!user) return NextResponse.json({ success: false, error: 'No autorizado' }, { status: 401 })

  let body: { pack_id?: string; shop_id?: string; quantity?: number; payment_method?: string }
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ success: false, error: 'Cuerpo de solicitud inválido' }, { status: 400 })
  }

  if (!body.pack_id || !body.shop_id) {
    return NextResponse.json({ success: false, error: 'Faltan campos requeridos: pack_id, shop_id' }, { status: 400 })
  }

  const quantity =
    typeof body.quantity === 'number' && body.quantity > 0 && Number.isInteger(body.quantity) ? body.quantity : 1

  const result = (await createReservation(user.id, { pack_id: body.pack_id, shop_id: body.shop_id, quantity })) as {
    error?: string
    status?: number
    data?: unknown
  }
  if (result.error) return NextResponse.json({ success: false, error: result.error }, { status: result.status ?? 500 })
  return NextResponse.json({ success: true, reservation: result.data }, { status: result.status ?? 201 })
}

export async function PUT(request: Request) {
  const user = await authenticateUser()
  if (!user) return NextResponse.json({ success: false, error: 'No autorizado' }, { status: 401 })

  let body: { id?: string; status?: string; cancel_reason?: string; pickup_code?: string }
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ success: false, error: 'Cuerpo de solicitud inválido' }, { status: 400 })
  }

  // Para validar pickup por código
  if (body.status === 'validate_pickup') {
    const supabase = await createClient()
    const { data: result, error } = await supabase.rpc('validate_pickup', {
      p_pickup_code: body.pickup_code ?? '',
    })
    if (error) return NextResponse.json({ success: false, error: error.message }, { status: 500 })
    const rpcResult = result as { success: boolean; error?: string }
    if (!rpcResult.success) {
      return NextResponse.json({ success: false, error: rpcResult.error ?? 'Código inválido' }, { status: 400 })
    }
    return NextResponse.json({ success: true, data: rpcResult })
  }

  // Para cancelar: usar RPC cancel_reservation (reintegra stock, actualiza stats)
  if (body.status === 'cancelled') {
    if (!body.id) {
      return NextResponse.json({ success: false, error: 'ID de reserva requerido' }, { status: 400 })
    }
    const supabase = await createClient()
    const { data: result, error } = await supabase.rpc('cancel_reservation', {
      p_reservation_id: body.id,
      p_cancel_reason: body.cancel_reason ?? null,
    })
    if (error) return NextResponse.json({ success: false, error: error.message }, { status: 500 })
    const rpcResult = result as { success: boolean; error?: string; message?: string }
    if (!rpcResult.success) {
      return NextResponse.json({ success: false, error: rpcResult.error ?? 'Error al cancelar' }, { status: 400 })
    }
    return NextResponse.json({ success: true, message: rpcResult.message ?? 'Reserva cancelada' })
  }

  // Para otros cambios de estado (confirmed, etc.)
  const validStatuses = ['pending', 'confirmed', 'picked_up', 'no_show']
  if (!validStatuses.includes(body.status ?? '')) {
    return NextResponse.json({ success: false, error: 'Status no válido' }, { status: 400 })
  }

  const result = (await updateReservation(user.id, body as { id: string; status: string; cancel_reason?: string })) as {
    error?: string
    status?: number
    data?: unknown
  }
  if (result.error) return NextResponse.json({ success: false, error: result.error }, { status: result.status ?? 500 })
  return NextResponse.json({ success: true, reservation: result.data })
}

import { createClient } from '@/lib/supabase/server'
import { NextResponse } from 'next/server'

const DEFAULT_PAGE_SIZE = 20
const MAX_PAGE_SIZE = 50
const MAX_PRICE_CENTS = 1_000_000_00

const cacheHeaders = {
  'Cache-Control': 'public, s-maxage=30, stale-while-revalidate=60',
}

function safeParseInt(value: string | null, defaultValue: number, min: number, max: number): number {
  if (!value) return defaultValue
  const parsed = parseInt(value, 10)
  if (isNaN(parsed)) return defaultValue
  return Math.max(min, Math.min(max, parsed))
}

export async function GET(request: Request) {
  const supabase = await createClient()
  const { searchParams } = new URL(request.url)

  const query = searchParams.get('q') || ''
  const type = searchParams.get('type') || 'packs'
  const page = safeParseInt(searchParams.get('page'), 1, 1, 10000)
  const pageSize = safeParseInt(searchParams.get('limit'), DEFAULT_PAGE_SIZE, 1, MAX_PAGE_SIZE)
  const offset = (page - 1) * pageSize

  const minPrice = safeParseInt(searchParams.get('minPrice'), 0, 0, MAX_PRICE_CENTS)
  const maxPrice = safeParseInt(searchParams.get('maxPrice'), MAX_PRICE_CENTS, 0, MAX_PRICE_CENTS)
  const city = searchParams.get('city') || ''
  const availableOnly = searchParams.get('available') === 'true'

  const now = new Date().toISOString()

  try {
    if (type === 'shops') {
      let builder = supabase.from('shops').select('*', { count: 'exact' }).is('deleted_at', null)

      if (query) {
        builder = builder.textSearch('search_vector', query, { type: 'websearch', config: 'spanish' })
      }

      if (city && city.length <= 100) {
        builder = builder.ilike('city', `%${city}%`)
      }

      builder = builder.order('rating', { ascending: false }).range(offset, offset + pageSize - 1)

      const { data, error, count } = await builder

      if (error) throw error

      return NextResponse.json(
        {
          success: true,
          results: data ?? [],
          total: count ?? 0,
          page,
          pageSize,
          totalPages: Math.ceil((count ?? 0) / pageSize),
        },
        { headers: cacheHeaders },
      )
    }

    let builder = supabase
      .from('packs')
      .select(
        `
        *,
        shop:shops (id, name, address, city, phone, verified, rating, logo_url)
      `,
        { count: 'exact' },
      )
      .eq('is_active', true)
      .is('deleted_at', null)

    if (availableOnly) {
      builder = builder.gt('remaining_stock', 0)
    }

    const filterOr = `pickup_date.is.null,pickup_end_time.is.null,and(pickup_date.not.is.null,pickup_end_time.not.is.null,concat(pickup_date,' ',pickup_end_time).gt.${now})`
    builder = builder.or(filterOr)

    if (query) {
      builder = builder.textSearch('search_vector', query, { type: 'websearch', config: 'spanish' })
    }

    if (minPrice > 0) {
      builder = builder.gte('price_cents', minPrice)
    }

    if (maxPrice < MAX_PRICE_CENTS) {
      builder = builder.lte('price_cents', maxPrice)
    }

    if (city && city.length <= 100) {
      builder = builder.eq('shop.city', city)
    }

    builder = builder.order('created_at', { ascending: false }).range(offset, offset + pageSize - 1)

    const { data, error, count } = await builder

    if (error) throw error

    return NextResponse.json(
      {
        success: true,
        results: data ?? [],
        total: count ?? 0,
        page,
        pageSize,
        totalPages: Math.ceil((count ?? 0) / pageSize),
      },
      { headers: cacheHeaders },
    )
  } catch (error) {
    console.error('[Search] Error:', error)
    return NextResponse.json(
      { success: false, error: error instanceof Error ? error.message : 'Error en la búsqueda' },
      { status: 500 },
    )
  }
}

import { NextResponse } from 'next/server'
import { createClient } from '@/lib/supabase/server'

export interface CommunityStats {
  packsRescued: number
  moneySavedCents: number
  co2SavedKg: number
  activeShops: number
  activePacks: number
}

export async function GET() {
  try {
    const supabase = await createClient()

    // Packs rescatados (reservas recogidas)
    const { count: packsRescued } = await supabase
      .from('reservations')
      .select('*', { count: 'exact', head: true })
      .eq('status', 'picked_up')

    // Dinero ahorrado (precio original - precio pagado en packs recogidos)
    const { data: savings } = await supabase
      .from('reservations')
      .select('total_price_cents, pack:packs(price_cents, original_price_cents)')
      .eq('status', 'picked_up')

    let moneySavedCents = 0
    if (savings) {
      for (const r of savings) {
        const pack = r.pack as { price_cents: number; original_price_cents: number | null } | null
        if (pack?.original_price_cents && pack.original_price_cents > pack.price_cents) {
          moneySavedCents += (pack.original_price_cents - pack.price_cents) * ((r as { quantity?: number }).quantity ?? 1)
        }
      }
    }

    // CO2 ahorrado (~2.5 kg por pack rescatado, estimación conservadora FAO)
    const co2SavedKg = (packsRescued ?? 0) * 2.5

    // Comercios activos
    const { count: activeShops } = await supabase
      .from('shops')
      .select('*', { count: 'exact', head: true })
      .eq('verified', true)
      .is('deleted_at', null)

    // Packs activos
    const { count: activePacks } = await supabase
      .from('packs')
      .select('*', { count: 'exact', head: true })
      .eq('is_active', true)
      .is('deleted_at', null)

    return NextResponse.json({
      success: true,
      stats: {
        packsRescued: packsRescued ?? 0,
        moneySavedCents,
        co2SavedKg,
        activeShops: activeShops ?? 0,
        activePacks: activePacks ?? 0,
      } satisfies CommunityStats,
    })
  } catch (error) {
    console.error('[Stats API] Error:', error)
    return NextResponse.json({ success: false, error: 'Error obteniendo estadísticas' }, { status: 500 })
  }
}

