async function sendEmail(params: { to: string; subject: string; html: string; text: string }) {
  const { to, subject, html, text } = params
  try {
    const { data, error } = await resend.emails.send({
      from: `Paporla <${senderEmail}>`,
      to,
      subject,
      html,
      text,
    })
    if (error) {
