'use client'

import { useState, useEffect, useMemo } from 'react'
import { useRouter } from 'next/navigation'
import { supabaseBrowser } from '@/lib/supabase/client'
import Link from 'next/link'
import { motion, AnimatePresence } from 'framer-motion'
import { Lock, ArrowLeft, CheckCircle, Eye, EyeOff, Check, X } from 'lucide-react'
import Button from '@/components/ui/Button'
import Input from '@/components/ui/Input'
import Toast from '@/components/ui/Toast'

export default function ResetPasswordPage() {
  const supabase = supabaseBrowser()
  const [password, setPassword] = useState('')
  const [confirmPassword, setConfirmPassword] = useState('')
  const [showPassword, setShowPassword] = useState(false)
  const [loading, setLoading] = useState(false)
  const [success, setSuccess] = useState(false)
  const [error, setError] = useState('')
  const router = useRouter()

  // Requisitos de contraseña en tiempo real
  const passwordChecks = useMemo(() => {
    const pwd = password
    return [
      { label: 'Al menos 8 caracteres', passed: pwd.length >= 8 },
      { label: 'Una letra mayuscula', passed: /[A-Z]/.test(pwd) },
      { label: 'Un numero', passed: /[0-9]/.test(pwd) },
    ]
  }, [password])

  const allPasswordChecksPassed = passwordChecks.every((c) => c.passed)
  const showPasswordHints = password.length > 0 && !allPasswordChecksPassed

  useEffect(() => {
    const hash = window.location.hash
    if (!hash.includes('access_token')) {
      setError('Enlace invalido o expirado. Por favor, solicita un nuevo enlace de recuperacion.')
    }
  }, [])

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setLoading(true)
    setError('')

    if (password !== confirmPassword) {
      setError('Las contraseñas no coinciden')
      setLoading(false)
      return
    }

    if (password.length < 8) {
      setError('La contraseña debe tener al menos 8 caracteres')
      setLoading(false)
      return
    }

    const { error: updateError } = await supabase.auth.updateUser({ password })

    if (updateError) {
      setError(updateError.message)
    } else {
      setSuccess(true)
      setTimeout(() => router.push('/login'), 3000)
    }
    setLoading(false)
  }

  if (success) {
    return (
      <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="text-center space-y-4">
        <div className="w-16 h-16 dark:bg-green-500/20 bg-green-100 rounded-full flex items-center justify-center mx-auto">
          <CheckCircle className="w-8 h-8 dark:text-green-400 text-green-600" />
        </div>
        <h2 className="text-2xl font-bold">
          <span className="text-gradient">Contrasena actualizada!</span>
        </h2>
        <p className="dark:text-gray-400 text-gray-600">Tu contraseña ha sido cambiada exitosamente.</p>
        <p className="text-sm dark:text-gray-500 text-gray-400">Seras redirigido al inicio de sesion...</p>
        <Link href="/login" className="text-primary hover:underline inline-flex items-center gap-1 mt-2">
          Ir ahora <ArrowLeft className="w-4 h-4" />
        </Link>
      </motion.div>
    )
  }

  return (
    <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }}>
      <form onSubmit={handleSubmit} className="space-y-5">
        <p className="dark:text-gray-400 text-gray-600 text-sm text-center">Ingresa tu nueva contraseña segura.</p>

        <div className="relative">
          <Input
            label="Nueva contraseña"
            type={showPassword ? 'text' : 'password'}
            placeholder="••••••••"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            icon={<Lock className="w-4 h-4" />}
            required
          />
          <button
            type="button"
            onClick={() => setShowPassword(!showPassword)}
            className="absolute right-3 top-9 dark:text-gray-400 text-gray-500 hover:text-primary transition-colors"
          >
            {showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
          </button>
        </div>

        {/* Requisitos de contraseña en tiempo real */}
        <AnimatePresence>
          {showPasswordHints && (
            <motion.div
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: 'auto' }}
              exit={{ opacity: 0, height: 0 }}
              className="overflow-hidden"
            >
              <div className="bg-gray-50 dark:bg-white/[0.03] rounded-xl p-3 border border-gray-100 dark:border-white/5 space-y-1.5">
                <p className="text-xs text-gray-500 dark:text-gray-500 mb-1">La contraseña debe tener:</p>
                {passwordChecks.map((check) => (
                  <div key={check.label} className="flex items-center gap-2 text-xs">
                    {check.passed ? (
                      <Check className="w-3.5 h-3.5 text-green-500 flex-shrink-0" />
                    ) : (
                      <X className="w-3.5 h-3.5 text-gray-400 flex-shrink-0" />
                    )}
                    <span
                      className={
                        check.passed ? 'text-green-600 dark:text-green-400' : 'text-gray-500 dark:text-gray-400'
                      }
                    >
                      {check.label}
                    </span>
                  </div>
                ))}
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        <Input
          label="Confirmar nueva contraseña"
          type="password"
          placeholder="••••••••"
          value={confirmPassword}
          onChange={(e) => setConfirmPassword(e.target.value)}
          icon={<Lock className="w-4 h-4" />}
          required
        />

        <Button type="submit" className="w-full" disabled={loading}>
          {loading ? 'Actualizando...' : 'Actualizar contraseña'}
        </Button>

        <div className="text-center">
          <Link
            href="/login"
            className="text-sm dark:text-gray-400 text-gray-600 hover:text-primary inline-flex items-center gap-1"
          >
            <ArrowLeft className="w-4 h-4" />
            Volver al inicio de sesion
          </Link>
        </div>
      </form>

      {error && <Toast message={error} type="error" onClose={() => setError('')} />}
    </motion.div>
  )
}

import { createClient } from '@/lib/supabase/server'

import { NextResponse } from 'next/server'

export async function GET(request: Request) {
  const requestUrl = new URL(request.url)
  const code = requestUrl.searchParams.get('code')

  if (code) {
    const supabase = await createClient()

    const { error } = await supabase.auth.exchangeCodeForSession(code)

    if (error) {
      console.error('Error en auth callback:', error)
      return NextResponse.redirect(new URL('/login?error=auth_callback', request.url))
    }

    const {
      data: { user },
    } = await supabase.auth.getUser()

    if (!user) {
      return NextResponse.redirect(new URL('/login', request.url))
    }

    const { data: profile } = await supabase.from('user_profiles').select('role, name').eq('id', user.id).maybeSingle()

    const role = profile?.role ?? 'user'

    // Enviar email de bienvenida (no bloqueante)
    if (user.email) {
      const baseUrl = process.env.NEXT_PUBLIC_SITE_URL ?? requestUrl.origin
      fetch(`${baseUrl}/api/email`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          type: 'welcome',
          email: user.email,
          data: { name: profile?.name ?? 'Usuario' },
        }),
      }).catch((err) => console.error('[Callback] Error welcome email:', err))
    }

    if (role === 'comercio') {
      return NextResponse.redirect(new URL('/business', request.url))
    }

    if (role === 'admin' || role === 'super_admin') {
      return NextResponse.redirect(new URL('/admin', request.url))
    }

    return NextResponse.redirect(new URL('/dashboard', request.url))
  }

  return NextResponse.redirect(new URL('/login', request.url))
}

'use client'

import { useMemo } from 'react'
import Link from 'next/link'
import { motion } from 'framer-motion'
import { pageVariants } from '@/lib/utils/motion'
import { useAuth } from '@/hooks/useAuth'
import { useReservations } from '@/hooks/useReservations'
import UserWelcomeBanner from '@/components/dashboard/UserWelcomeBanner'
import UserStatsGrid from '@/components/dashboard/UserStatsGrid'
import UserQuickActions from '@/components/dashboard/UserQuickActions'
import NextPickupCard from '@/components/dashboard/NextPickupCard'
import RecentActivity from '@/components/dashboard/RecentActivity'
import DashboardSkeleton from '@/components/dashboard/DashboardSkeleton'
import Toast from '@/components/ui/Toast'
import { sortReservationsByPickupTime } from '@/lib/constants/reservations'
import type { ReservationWithDetails } from '@/types/reservation'

export default function UserDashboardPage() {
  const { user } = useAuth()
  const { reservations, loading, error: hookError } = useReservations()

  const { activeReservations, stats, activities } = useMemo(() => {
    const valid = reservations.filter((r): r is ReservationWithDetails => !!r.pack && !!r.shop)
    const active = sortReservationsByPickupTime(valid.filter((r) => ['confirmed', 'pending'].includes(r.status)))
    const completed = valid.filter((r) => r.status === 'picked_up')

    const totalPacksRescued = completed.length
    const co2Saved = Math.round(totalPacksRescued * 1.2)
    const moneySavedCents = completed.reduce((sum, r) => sum + (r.total_price_cents ?? 0), 0)
    const points = totalPacksRescued * 10

    let level = 'Aprendiz'
    if (points >= 500) level = 'Rescatador Elite'
    else if (points >= 200) level = 'Rescatador Pro'
    else if (points >= 50) level = 'Rescatador Avanzado'
    else if (points >= 10) level = 'Rescatador'

    const recentActivities = valid.slice(0, 5).map((r) => ({
      id: r.id,
      type: 'reservation' as const,
      title: r.pack.title,
      description: `${r.shop.name} - ${r.quantity ?? 1}x`,
      status: r.status,
      created_at: r.created_at,
      link: '/reservations',
    }))

    return {
      activeReservations: active,
      stats: {
        activeReservations: active.length,
        totalPacksRescued,
        co2Saved,
        moneySaved: moneySavedCents / 100,
        points,
        level,
      },
      activities: recentActivities,
    }
  }, [reservations])

  if (loading) return <DashboardSkeleton />

  const nextReservation = activeReservations[0]

  return (
    <motion.div variants={pageVariants} initial="initial" animate="animate" className="space-y-8 pb-8">
      <UserWelcomeBanner
        userName={user?.name ?? 'Usuario'}
        packsRescued={stats.totalPacksRescued}
        level={stats.level}
        points={stats.points}
      />

      <UserStatsGrid stats={stats} />

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <UserQuickActions />

        {nextReservation ? (
          <div className="space-y-4">
            <div className="flex items-center gap-2">
              <div className="w-1 h-5 bg-primary rounded-full" />
              <h2 className="text-lg font-semibold dark:text-white text-gray-900">Proxima recogida</h2>
            </div>
            <NextPickupCard reservation={nextReservation} />
          </div>
        ) : (
          <div className="glass-card border-dashed border-primary/30 rounded-2xl p-8 text-center">
            <p className="dark:text-gray-400 text-gray-600">No tienes reservas activas</p>
            <Link href="/packs" className="text-primary text-sm hover:underline inline-block mt-2">
              Explora packs disponibles
            </Link>
          </div>
        )}
      </div>

      <RecentActivity activities={activities} />

      {hookError && <Toast message={hookError} type="error" onClose={() => {}} />}
    </motion.div>
  )
}

﻿'use client'

import { useState } from 'react'
import { motion } from 'framer-motion'
import { pageVariants } from '@/lib/utils/motion'
import { Bell, CheckCheck, Trash2, Clock, Package, CheckCircle, XCircle, AlertCircle, Store, Heart } from 'lucide-react'
import { useNotifications } from '@/hooks/useNotifications'
import Card from '@/components/ui/Card'
import Button from '@/components/ui/Button'
import EmptyState from '@/components/ui/EmptyState'
import Toast from '@/components/ui/Toast'

const iconMap: Record<string, { icon: React.ComponentType<{ className?: string }>; color: string; bg: string }> = {
  pickup_reminder: { icon: Clock, color: 'text-amber-400', bg: 'bg-amber-500/10' },
  cancellation: { icon: XCircle, color: 'text-red-400', bg: 'bg-red-500/10' },
  confirmation: { icon: CheckCircle, color: 'text-green-400', bg: 'bg-green-500/10' },
  new_pack: { icon: Package, color: 'text-primary', bg: 'bg-primary/10' },
  new_reservation: { icon: Package, color: 'text-primary', bg: 'bg-primary/10' },
  pick_up: { icon: CheckCircle, color: 'text-green-400', bg: 'bg-green-500/10' },
  favorite: { icon: Heart, color: 'text-red-400', bg: 'bg-red-500/10' },
  shop_verified: { icon: Store, color: 'text-blue-400', bg: 'bg-blue-500/10' },
  incidence: { icon: AlertCircle, color: 'text-red-400', bg: 'bg-red-500/10' },
}

const defaultIcon = { icon: Bell, color: 'text-gray-400', bg: 'bg-gray-500/10' }

export default function NotificationsPage() {
  const { notifications, unreadCount, loading, markAsRead, markAllAsRead, deleteNotification } = useNotifications()
  const [filter, setFilter] = useState<'all' | 'unread'>('all')
  const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' } | null>(null)

  const formatTime = (date: string) => {
    const now = new Date()
    const target = new Date(date)
    const diffMins = Math.floor((now.getTime() - target.getTime()) / 60000)
    if (diffMins < 1) return 'Justo ahora'
    if (diffMins < 60) return `Hace ${diffMins} min`
    if (diffMins < 1440) return `Hace ${Math.floor(diffMins / 60)} h`
    return target.toLocaleDateString()
  }

  const filteredNotifications = filter === 'all' ? notifications : notifications.filter((n) => !n.is_read)

  // SPINNER
  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[60vh]">
        <div className="text-center">
          <div className="w-14 h-14 rounded-full border-4 border-primary/30 border-t-primary animate-spin mx-auto mb-4" />
          <p className="dark:text-gray-400 text-gray-600 text-lg font-medium">Cargando notificaciones...</p>
          <p className="dark:text-gray-600 text-gray-400 text-sm mt-1">Por favor espera</p>
        </div>
      </div>
    )
  }

  return (
    <motion.div variants={pageVariants} initial="initial" animate="animate" className="space-y-8 pb-8">
      <div className="relative overflow-hidden bg-gradient-to-br from-primary/5 via-transparent to-secondary/5 -mt-8 -mx-4 px-4 py-8 rounded-b-3xl">
        <div className="relative flex justify-between items-center">
          <div>
            <div className="flex items-center gap-3 mb-2">
              <div className="w-10 h-10 rounded-xl bg-primary/10 flex items-center justify-center">
                <Bell className="w-5 h-5 text-primary" />
              </div>
              <h1 className="text-3xl md:text-4xl font-bold dark:text-white text-gray-900">Notificaciones</h1>
              {unreadCount > 0 && (
                <span className="text-sm bg-primary/20 text-primary px-2.5 py-1 rounded-full">
                  {unreadCount} nuevas
                </span>
              )}
            </div>
            <p className="dark:text-gray-400 text-gray-600">Mantente al dia con tus reservas y novedades</p>
          </div>
          {unreadCount > 0 && (
            <Button
              variant="outline"
              size="sm"
              onClick={() => {
                markAllAsRead()
                setToast({ message: 'Todas marcadas como leidas', type: 'success' })
                setTimeout(() => setToast(null), 2000)
              }}
              className="flex items-center gap-1"
            >
              <CheckCheck className="w-4 h-4" />
              Marcar todas
            </Button>
          )}
        </div>
      </div>

      <div className="flex gap-2">
        <button
          onClick={() => setFilter('all')}
          className={`px-4 py-2 rounded-lg text-sm font-medium transition-all ${
            filter === 'all'
              ? 'bg-primary/20 text-primary border border-primary/30'
              : 'dark:bg-dark-muted bg-gray-100 dark:text-gray-400 text-gray-600 hover:dark:text-white hover:text-gray-900'
          }`}
        >
          Todas
        </button>
        <button
          onClick={() => setFilter('unread')}
          className={`px-4 py-2 rounded-lg text-sm font-medium transition-all ${
            filter === 'unread'
              ? 'bg-primary/20 text-primary border border-primary/30'
              : 'dark:bg-dark-muted bg-gray-100 dark:text-gray-400 text-gray-600 hover:dark:text-white hover:text-gray-900'
          }`}
        >
          No leidas
          {unreadCount > 0 && (
            <span className="ml-1.5 text-xs bg-primary/30 px-1.5 py-0.5 rounded-full">{unreadCount}</span>
          )}
        </button>
      </div>

      {filteredNotifications.length === 0 ? (
        <EmptyState
          type="notifications"
          action={{ label: 'Explorar packs', onClick: () => (window.location.href = '/packs') }}
        />
      ) : (
        <div className="space-y-3">
          {filteredNotifications.map((notification, idx) => {
            const { icon: Icon, color, bg } = iconMap[notification.type] || defaultIcon
            const isUnread = !notification.is_read

            return (
              <motion.div
                key={notification.id}
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: idx * 0.03 }}
                onClick={() => isUnread && markAsRead(notification.id)}
                className={`cursor-pointer transition-all duration-200 ${isUnread ? 'border-l-2 border-primary' : ''}`}
              >
                <Card glass className="p-5 group hover:border-primary/30">
                  <div className="flex gap-4">
                    <div className={`p-2.5 rounded-xl ${bg} flex-shrink-0`}>
                      <Icon className={`w-5 h-5 ${color}`} />
                    </div>
                    <div className="flex-1 min-w-0">
                      <p
                        className={`text-sm ${isUnread ? 'dark:text-white text-gray-900 font-medium' : 'dark:text-gray-400 text-gray-600'}`}
                      >
                        {notification.message}
                      </p>
                      <div className="flex items-center gap-3 mt-2">
                        <span className="text-[10px] text-gray-500 flex items-center gap-1">
                          <Clock className="w-3 h-3" />
                          {formatTime(notification.created_at)}
                        </span>
                      </div>
                    </div>
                    <button
                      onClick={(e) => {
                        e.stopPropagation()
                        deleteNotification(notification.id)
                        setToast({ message: 'Notificacion eliminada', type: 'success' })
                        setTimeout(() => setToast(null), 2000)
                      }}
                      className="p-1.5 rounded-lg text-gray-500 hover:text-red-400 hover:bg-red-500/10 transition-all opacity-0 group-hover:opacity-100"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                </Card>
              </motion.div>
            )
          })}
        </div>
      )}

      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
    </motion.div>
  )
}

