// @ts-nocheck
// ============================================
// SUPABASE EDGE FUNCTION
// Limpieza de reservas pendientes vencidas
// ============================================
//
// CÓMO DESPLEGAR:
// supabase functions deploy cleanup-reservations --no-verify-jwt
//
// CÓMO CONFIGURAR CRON-JOB.ORG:
// URL: https://tu-proyecto.supabase.co/functions/v1/cleanup-reservations
// Method: GET
// Schedule: */5 * * * *
// Headers: Authorization: Bearer TU_CLAVE_SECRETA
// ============================================

import { serve } from 'https://deno.land/std@0.177.0/http/server.ts'
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'

serve(async (req) => {
  try {
    // 1. Verificar autorización (evita que cualquiera ejecute esta función)
    const authHeader = req.headers.get('Authorization')
    const cronJobSecret = Deno.env.get('CRON_JOB_SECRET')

    if (cronJobSecret && authHeader !== `Bearer ${cronJobSecret}`) {
      console.log('❌ Acceso no autorizado')
      return new Response(JSON.stringify({ success: false, error: 'No autorizado' }), {
        headers: { 'Content-Type': 'application/json' },
        status: 401,
      })
    }

    // 2. Crear cliente de Supabase con permisos de administrador
    const supabase = createClient(Deno.env.get('SUPABASE_URL')!, Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!)

    // 3. Ejecutar la función SQL que limpia reservas pendientes
    const { data, error } = await supabase.rpc('cleanup_pending_reservations')

    if (error) {
      console.error('❌ Error al ejecutar cleanup_pending_reservations:', error)
      throw error
    }

    const expiredCount = data || 0

    console.log(`✅ ${expiredCount} reservas pendientes canceladas por timeout`)

    // 4. Responder con éxito
    return new Response(
      JSON.stringify({
        success: true,
        expired: expiredCount,
        message: `${expiredCount} reservas pendientes canceladas y stock reintegrado`,
        timestamp: new Date().toISOString(),
      }),
      {
        headers: { 'Content-Type': 'application/json' },
        status: 200,
      },
    )
  } catch (error) {
    console.error('❌ Error general en cleanup-reservations:', error)

    return new Response(
      JSON.stringify({
        success: false,
        error: error instanceof Error ? error.message : 'Error desconocido',
        timestamp: new Date().toISOString(),
      }),
      {
        headers: { 'Content-Type': 'application/json' },
        status: 500,
      },
    )
  }
})

import { NextRequest, NextResponse } from 'next/server'
import crypto from 'crypto'

// ============================================
// CSRF Protection — Double-submit cookie pattern
// ============================================
//
// Genera un token CSRF por sesión, lo almacena en una cookie
// y exige que las mutaciones API incluyan el mismo token
// en el header X-CSRF-Token.
//
// La cookie NO tiene HttpOnly para que el cliente JS pueda leerla
// y enviarla de vuelta en el header. Esto es seguro porque:
// - Un atacante en otro dominio no puede leer la cookie (SameSite Lax)
// - Un atacante no puede escribir el header desde otro origen (CORS)

const CSRF_COOKIE = 'csrf_token'
const CSRF_HEADER = 'X-CSRF-Token'

function generateToken(): string {
  return crypto.randomBytes(32).toString('hex')
}

/**
 * Aplica la cookie CSRF a la respuesta si no existe.
 * Debe llamarse en middleware.ts en la respuesta next().
 */
export function setCsrfCookie(response: NextResponse, existingToken?: string): string {
  const token = existingToken ?? generateToken()
  response.cookies.set(CSRF_COOKIE, token, {
    httpOnly: false, // El cliente necesita leerla para enviarla en el header
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    path: '/',
    maxAge: 60 * 60 * 24, // 24 horas
  })
  return token
}

/**
 * Valida que la petición incluya el token CSRF correcto.
 * Retorna null si es válido, o un NextResponse de error si no.
 */
export function validateCsrf(request: NextRequest): NextResponse | null {
  // Solo validar mutaciones
  const method = request.method
  if (!['POST', 'PUT', 'PATCH', 'DELETE'].includes(method)) {
    return null
  }

  const cookieToken = request.cookies.get(CSRF_COOKIE)?.value
  const headerToken = request.headers.get(CSRF_HEADER)

  if (!cookieToken || !headerToken) {
    return NextResponse.json(
      { success: false, error: 'Token CSRF requerido para mutaciones' },
      { status: 403 },
    )
  }

  // Comparación en tiempo constante para evitar timing attacks
  if (cookieToken.length !== headerToken.length) {
    return NextResponse.json(
      { success: false, error: 'Token CSRF inválido' },
      { status: 403 },
    )
  }

  const valid = crypto.timingSafeEqual(Buffer.from(cookieToken), Buffer.from(headerToken))
  if (!valid) {
    return NextResponse.json(
      { success: false, error: 'Token CSRF inválido' },
      { status: 403 },
    )
  }

  return null
}

